  "lines": [
    {
      "id": "repertoire.exercise_weeks",
      "tiers": [
        {
          "id": "repertoire.exercise_weeks:t1",
          "title": "Знакомая скамья",
          "phrase": "Ты выполнил одно и то же упражнение в 3 разных неделях. Железо уже придерживает тебе дверь!",
          "imagePrompt": "A small anthropomorphic kettlebell carrying a striped gym bag enters a tiny inn shaped like an exercise bench. Its handle tilts toward an open seat-lid doorway, where a folded towel waits on a little check-in shelf.",
          "fishMarkup": "[warm]Ты выполнил одно и то же упражнение в 3 разных неделях. Железо уже <emphasis>придерживает тебе дверь!</emphasis>",
          "audioText": "Ты выполнил одно и то же упражнение в 3 разных неделях. Железо уже придерживает тебе дверь!"
        },
        {
          "id": "repertoire.exercise_weeks:t2",
          "title": "Твоё обычное",
          "phrase": "У тебя уже 8 разных недель с одним и тем же упражнением. Оно узнаёт тебя без вопроса «Вам как обычно?».",
          "imagePrompt": "An anthropomorphic kettlebell with a striped gym bag confidently settles into its familiar nook inside an exercise-bench inn. A tiny towel valet has already pulled out its stool, and its bag fits a dedicated cubby.",
          "fishMarkup": "[confident]У тебя уже 8 разных недель с одним и тем же упражнением. Оно узнаёт тебя без вопроса <emphasis>«Вам как обычно?».</emphasis>",
          "audioText": "У тебя уже 8 разных недель с одним и тем же упражнением. Оно узнаёт тебя без вопроса «Вам как обычно?»."
        },
        {
          "id": "repertoire.exercise_weeks:t3",
          "title": "Пульт от спортзала",
          "phrase": "В твоей истории — 16 разных недель с одним и тем же упражнением. Оно уже выдало тебе тапочки и пульт от спортзала!",
          "imagePrompt": "An anthropomorphic kettlebell lounges in a bathrobe inside an exercise-bench inn, its striped gym bag under the chair. A tiny towel butler presents giant fluffy slippers on a tray while the guest points a remote at a treadmill.",
          "fishMarkup": "[triumphant]В твоей истории — 16 разных недель с одним и тем же упражнением. Оно уже выдало тебе <slow>тапочки и пульт от спортзала!</slow>",
          "audioText": "В твоей истории — 16 разных недель с одним и тем же упражнением. Оно уже выдало тебе тапочки и пульт от спортзала!"
        }
      ]
    },
    {
      "id": "repertoire.new_exercise_months",
      "tiers": [
        {
          "id": "repertoire.new_exercise_months:t1",
          "title": "Крот вышел в разведку",
          "phrase": "В 2 разных месяцах ты впервые выполнял новые упражнения. Крот-картограф выглянул из привычного тоннеля: о, тут ещё целый зал!",
          "imagePrompt": "A curious mole cartographer in a headlamp emerges from a tunnel with an open folding atlas. Two freshly uncovered alcoves hold a resistance band and a step platform, and the mole marks their locations with blank tabs.",
          "fishMarkup": "[warm]В 2 разных месяцах ты впервые выполнял новые упражнения. Крот-картограф выглянул из привычного тоннеля: <emphasis>о, тут ещё целый зал!</emphasis>",
          "audioText": "В 2 разных месяцах ты впервые выполнял новые упражнения. Крот-картограф выглянул из привычного тоннеля: о, тут ещё целый зал!"
        },
        {
          "id": "repertoire.new_exercise_months:t2",
          "title": "Атласу тесно",
          "phrase": "Набралось 4 разных месяца, в которых ты впервые выполнял новые упражнения. Крот-картограф раскрыл атлас — на коленях уже тесно!",
          "imagePrompt": "A mole cartographer in a headlamp wrestles with a folding atlas spilling across a worktable. Four branching tunnels reveal a band, a step, a bench and a bar; the mole uses both paws to stop the expanding map sliding away.",
          "fishMarkup": "[confident]Набралось 4 разных месяца, в которых ты впервые выполнял новые упражнения. Крот-картограф раскрыл атлас — <emphasis>на коленях уже тесно!</emphasis>",
          "audioText": "Набралось 4 разных месяца, в которых ты впервые выполнял новые упражнения. Крот-картограф раскрыл атлас — на коленях уже тесно!"
        },
        {
          "id": "repertoire.new_exercise_months:t3",
          "title": "Глобус с пропиской",
          "phrase": "В 8 разных месяцах ты впервые выполнял новые упражнения. Твой атлас разросся: крот-картограф теперь живёт в глобусе!",
          "imagePrompt": "A mole cartographer in a headlamp lounges inside a huge hinged globe turned into a home. Its enormous folding atlas spills out as a front path, and a resistance band stretched between the globe's halves holds tiny freshly washed socks.",
          "fishMarkup": "[triumphant]В 8 разных месяцах ты впервые выполнял новые упражнения. Твой атлас разросся: <slow>крот-картограф теперь живёт в глобусе!</slow>",
          "audioText": "В 8 разных месяцах ты впервые выполнял новые упражнения. Твой атлас разросся: крот-картограф теперь живёт в глобусе!"
        }
      ]
    }
  ]
}
